package fastgrid;

public class Cell {

    // Original ratios
    public final float ratioW;
    public final float ratioH;

    // Precomputed for speed
    public final float aspect;     // ratioW / ratioH

    // Layout rectangles (Primitive float Rects instead of Rectangle2D.Float)
    public final Rect outer = new Rect();
    public final Rect inner = new Rect();

    // Optional: index for stable animations / ordering
    public int index;

    public Cell(float rw, float rh) {
        this.ratioW = rw;
        this.ratioH = rh;
        this.aspect = rw / rh;
    }
}

package fastgrid;

import java.util.Arrays;
import java.util.List;

public final class GridLayout implements LayoutAlgorithm {

    @Override
    public LayoutMeasure measure(List<Cell> cells, LayoutContext ctx) {
        int cols = Math.max(1, Math.round(ctx.columns()));
        float gap = ctx.gap();
        float usable = Math.max(1f, ctx.width() - gap * (cols + 1f));
        float size = Math.max(ctx.minSize(), usable / cols);

        float rows = (float) Math.ceil(cells.size() / (double) cols);
        float height = rows * (size + gap) + gap;
        return new LayoutMeasure(height);
    }

    @Override
    public List<Rect> arrange(List<Cell> cells, LayoutContext ctx, LayoutMeasure m) {
        int cols = Math.max(1, Math.round(ctx.columns()));
        float gap = ctx.gap();
        float width = ctx.width();

        float usable = Math.max(1f, width - gap * (cols + 1f));
        float size = Math.max(ctx.minSize(), usable / cols);

        Rect[] out = new Rect[cells.size()];
        float x = gap;
        float y = gap;

        for (int i = 0; i < cells.size(); i++) {
            out[i] = new Rect(x, y, size, size);
            x += size + gap;
            if (x + size > width + 0.5f) {
                x = gap;
                y += size + gap;
            }
        }

        return Arrays.asList(out);
    }
}

package fastgrid.demo;

import fastgrid.*;

import java.awt.event.*;

public class GalleryWheelAdapter implements MouseWheelListener {

    private final FastGridView panel;
    private final LayoutController layout;
    private final AnimationController anim;
    private final InteractionController input;

    public GalleryWheelAdapter(FastGridView panel, LayoutController layout, AnimationController anim, InteractionController input) {
        this.panel  = panel;
        this.layout = layout;
        this.anim   = anim;
        this.input  = input;
    }

    @Override
    public void mouseWheelMoved(MouseWheelEvent e) {

        // ALT = GAP SCALING
        if (e.isAltDown()) {
            panel.gapScale += e.getWheelRotation() * 0.05f;
            panel.gapScale = Math.max(0.1f, Math.min(5f, panel.gapScale));
            layout.invalidate();
            panel.repaint();
            return;
        }

        // SHIFT = COLUMN SCALING
        if (e.isShiftDown()) {
            panel.columns -= e.getWheelRotation() * 0.25f;
            panel.columns = Math.max(2f, Math.min(40f, panel.columns));
            panel.targetColumns = panel.columns;
            layout.invalidate();
            panel.repaint();
            return;
        }

        // NORMAL SCROLL (smooth wheel)
        input.addScrollVelocity(-e.getWheelRotation() * 400f);
    }
}

package fastgrid;

import java.util.List;

public final class FastLayoutEngine {

    public static LayoutMeasure measure(
            LayoutAlgorithm algo,
            List<Cell> cells,
            float width,
            float gap,
            float minSize,
            float columns
    ) {
        LayoutContext ctx = LayoutContext.of(width, gap, minSize, columns);
        return algo.measure(cells, ctx);
    }

    public static List<Rect> arrange(
            LayoutAlgorithm algo,
            List<Cell> cells,
            float width,
            float gap,
            float minSize,
            float columns
    ) {
        LayoutContext ctx = LayoutContext.of(width, gap, minSize, columns);
        LayoutMeasure m = algo.measure(cells, ctx);
        return algo.arrange(cells, ctx, m);
    }
}

package fastgrid;

public record LayoutContext(
        float width,
        float gap,
        float minSize,
        float columns,
        float usableWidth,
        float columnWidth
) {
    public static LayoutContext of(float width, float gap, float minSize, float columns) {
        float cols = Math.max(1f, columns);
        float totalGap = gap * (cols + 1f);
        float usable = Math.max(1f, width - totalGap);
        float colWidth = Math.max(minSize, usable / cols);
        return new LayoutContext(width, gap, minSize, cols, usable, colWidth);
    }
}

package fastgrid.demo;

import fastgrid.*;

import java.awt.event.*;

public class InteractionController {

    private FastGridView panel;
    private LayoutController layout;
    private AnimationController anim;

    private int lastX = 0;
    private int lastY = 0;

    private boolean isColumnScaling = false;
    private boolean isGapScaling    = false;
    private boolean isScrolling     = false;

    private float velocityY   = 0f;
    private long lastDragTime = 0;
    private long lastTickTime = 0;
    private javax.swing.Timer momentumTimer;

    public final MouseListener mouseListener;
    public final MouseMotionListener mouseMotionListener;
    public final MouseWheelListener wheelListener;

    public InteractionController(FastGridView panel, LayoutController layout, AnimationController anim) {
        this.panel  = panel;
        this.layout = layout;
        this.anim   = anim;

        this.mouseListener       = createMouseListener();
        this.mouseMotionListener = createMouseMotionListener();
        this.wheelListener       = new GalleryWheelAdapter(panel, layout, anim, this);
    }

    public void addScrollVelocity(float v) {
        isScrolling = true;
        velocityY += v;
        if (momentumTimer == null || !momentumTimer.isRunning()) {
            startMomentum();
        }
    }

    private MouseListener createMouseListener() {
        return new MouseAdapter() {

            @Override
            public void mousePressed(MouseEvent e) {
                lastX = e.getX();
                lastY = e.getY();
                lastDragTime = System.nanoTime();
                velocityY = 0f;

                isColumnScaling = false;
                isGapScaling    = false;
                isScrolling     = false;

                stopMomentum();
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                if (isColumnScaling) {
                    anim.snapColumns(panel.columns);
                }
                startMomentum();
                isColumnScaling = false;
                isGapScaling    = false;
                isScrolling     = false;
            }
        };
    }

    private MouseMotionListener createMouseMotionListener() {
        return new MouseMotionAdapter() {

            @Override
            public void mouseDragged(MouseEvent e) {

                long now = System.nanoTime();
                float dtSec = (now - lastDragTime) / 1_000_000_000f;
                lastDragTime = now;

                int dx = e.getX() - lastX;
                int dy = e.getY() - lastY;

                lastX = e.getX();
                lastY = e.getY();

                // ALT = GAP SCALING
                if (e.isAltDown()) {
                    isGapScaling = true;
                    panel.gapScale += dx * 0.01f;
                    panel.gapScale = Math.max(0.1f, Math.min(5f, panel.gapScale));
                    layout.invalidate();
                    panel.repaint();
                    return;
                }

                // SHIFT = COLUMN SCALING
                if (e.isShiftDown()) {
                    isColumnScaling = true;
                    panel.columns -= dx * 0.02f;
                    panel.columns = Math.max(2f, Math.min(40f, panel.columns));
                    panel.targetColumns = panel.columns;
                    layout.invalidate();
                    panel.repaint();
                    return;
                }

                // NORMAL SCROLL (drag)
                isScrolling = true;
                panel.scroll(dy);
                velocityY = (dtSec > 0 && dtSec < 0.2f) ? (dy / dtSec) : 0f;
            }
        };
    }

    private void stopMomentum() {
        if (momentumTimer != null) {
            momentumTimer.stop();
            momentumTimer = null;
        }
    }

    private void startMomentum() {
        if (!isScrolling) return;
        stopMomentum();

        lastTickTime = System.nanoTime();
        momentumTimer = new javax.swing.Timer(16, e -> {
            long now = System.nanoTime();
            float dtSec = (now - lastTickTime) / 1_000_000_000f;
            lastTickTime = now;

            // Cap dt to prevent massive jumps if timer stalls
            if (dtSec > 0.1f) dtSec = 0.016f;

            if (Math.abs(velocityY) < 10f) {
                stopMomentum();
                return;
            }

            // Apply friction relative to time passed (0.92 per 16ms = ~0.005 per second decay)
            float friction = (float) Math.pow(0.92, dtSec / 0.016f);

            panel.scroll(velocityY * dtSec);
            velocityY *= friction;
        });

        momentumTimer.start();
    }
}

package fastgrid.demo;

import fastgrid.*;
import fastgrid.GridLayout;

import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class LayoutController {

    private final FastGridView panel;

    private List<Cell> cells = new ArrayList<>();

    private final LayoutAlgorithm gridAlgo    = new GridLayout();
    private final LayoutAlgorithm masonryAlgo = new MasonryLayout();
    private final LayoutAlgorithm galleryAlgo = new GalleryLayout();

    private LayoutAlgorithm currentAlgo = gridAlgo;

    private Rect[] sourceBounds;
    private Rect[] targetBounds;
    private Rect[] currentBounds;

    private boolean initialized = false;
    private float layoutT = 0f;

    public LayoutController(FastGridView panel) {
        this.panel = panel;
    }

    public void setCells(List<Cell> newCells) {
        this.cells = newCells;
        this.initialized = false; // force reallocation
    }

    public List<Cell> getCells() { return cells; }

    public float getLayoutT() { return layoutT; }

    public void setLayoutT(float t) {
        this.layoutT = t;
    }

    public void invalidate() {
        initialized = false;
    }

    public Dimension getPreferredSize() {
        if (cells.isEmpty()) return new Dimension(0, 0);
        LayoutContext ctx = createContext();
        LayoutMeasure m = currentAlgo.measure(cells, ctx);
        return new Dimension((int) ctx.width(), (int) m.height());
    }

    public void setMode(LayoutMode mode) {
        ensureInitialized();
        if (cells.isEmpty()) return;

        for (int i = 0; i < currentBounds.length; i++) {
            sourceBounds[i].set(currentBounds[i]);
        }

        currentAlgo = switch (mode) {
            case GRID    -> gridAlgo;
            case MASONRY -> masonryAlgo;
            case GALLERY -> galleryAlgo;
        };

        List<Rect> newTarget = compute(currentAlgo);
        for (int i = 0; i < targetBounds.length; i++) {
            targetBounds[i].set(newTarget.get(i));
        }

        layoutT = 0f;
    }

    public Rect[] getRects() {
        if (cells.isEmpty()) return new Rect[0];
        ensureInitialized();
        updateInterpolation();
        return currentBounds;
    }

    private LayoutContext createContext() {
        float width   = panel.getWidth() > 0 ? panel.getWidth() : 700;
        float gap     = Math.max(0f, panel.baseGap * panel.gapScale);
        float minSize = 24f;
        float cols    = panel.columns;
        return LayoutContext.of(width, gap, minSize, cols);
    }

    private void ensureInitialized() {
        if (initialized || cells.isEmpty()) return;

        int n = cells.size();
        sourceBounds  = allocRects(n);
        targetBounds  = allocRects(n);
        currentBounds = allocRects(n);

        List<Rect> initRects = compute(currentAlgo);
        for (int i = 0; i < n; i++) {
            sourceBounds[i].set(initRects.get(i));
            targetBounds[i].set(initRects.get(i));
            currentBounds[i].set(initRects.get(i));
        }

        layoutT = 1f;
        initialized = true;
    }

    private void updateInterpolation() {
        float t = Math.min(1f, Math.max(0f, layoutT));
        for (int i = 0; i < currentBounds.length; i++) {
            currentBounds[i].setLerp(sourceBounds[i], targetBounds[i], t);
        }
    }

    private List<Rect> compute(LayoutAlgorithm algo) {
        LayoutContext ctx = createContext();
        LayoutMeasure m   = algo.measure(cells, ctx);
        return algo.arrange(cells, ctx, m);
    }

    private static Rect[] allocRects(int n) {
        Rect[] arr = new Rect[n];
        for (int i = 0; i < n; i++) arr[i] = new Rect();
        return arr;
    }
}

package fastgrid;

import java.util.Arrays;
import java.util.List;

public final class MasonryLayout implements LayoutAlgorithm {

    @Override
    public LayoutMeasure measure(List<Cell> cells, LayoutContext ctx) {
        int cols = Math.max(1, Math.round(ctx.columns()));
        float gap = ctx.gap();

        float usable = Math.max(1f, ctx.width() - gap * (cols + 1f));
        float colW = Math.max(ctx.minSize(), usable / cols);

        // Plain float array — linear min search is faster than PriorityQueue for typical col counts
        float[] heights = new float[cols];
        Arrays.fill(heights, gap);

        for (Cell c : cells) {
            int col = LayoutMath.minIndex(heights);
            float h = LayoutMath.heightFor(c, colW, ctx.minSize());
            heights[col] += h + gap;
        }

        float max = 0f;
        for (float h : heights) max = Math.max(max, h);
        return new LayoutMeasure(max + gap);
    }

    @Override
    public List<Rect> arrange(List<Cell> cells, LayoutContext ctx, LayoutMeasure m) {
        int cols = Math.max(1, Math.round(ctx.columns()));
        float gap = ctx.gap();

        float usable = Math.max(1f, ctx.width() - gap * (cols + 1f));
        float colW = Math.max(ctx.minSize(), usable / cols);

        float[] heights = new float[cols];
        Arrays.fill(heights, gap);

        Rect[] out = new Rect[cells.size()];
        for (int i = 0; i < cells.size(); i++) {
            Cell c = cells.get(i);
            int col = LayoutMath.minIndex(heights);
            float h = LayoutMath.heightFor(c, colW, ctx.minSize());
            float x = gap + col * (colW + gap);
            float y = heights[col];
            out[i] = new Rect(x, y, colW, h);
            heights[col] += h + gap;
        }

        return Arrays.asList(out);
    }
}

package fastgrid.demo;

import fastgrid.Cell;
import fastgrid.Rect;
import fastproportion.Proportion;
import fastui.component.Component;

import java.awt.*;
import java.awt.image.BufferedImage;

public class CellComponent extends Component {

    public final Cell cell;
    public final FastGridView view;
    public BufferedImage image;  // optional — set after loading

    private final java.awt.geom.AffineTransform transform = new java.awt.geom.AffineTransform();
    private final java.awt.geom.Rectangle2D.Float fallbackRect = new java.awt.geom.Rectangle2D.Float();
    private final java.awt.geom.Rectangle2D.Float clipRect = new java.awt.geom.Rectangle2D.Float();

    private final Proportion proportion = new Proportion(0, 0, 0, 0);
    private final float[] pOut = new float[4];

    public CellComponent(FastGridView view, Cell cell) {
        this.view = view;
        this.cell = cell;
    }

    @Override
    public void onRender(Graphics2D g) {
        Rect outer = cell.outer;
        Rect inner = cell.inner;

        // Use FastProportion for computing inner bounds
        proportion.x = outer.x;
        proportion.y = outer.y;
        proportion.width = outer.w;
        proportion.height = outer.h;
        // The intrinsic aspect ratio of the image is cell.aspect. We use a 1x1 base and scale it:
        proportion.contentWidth = cell.aspect;
        proportion.contentHeight = 1f;

        proportion.compute(view.proportionMode, pOut);
        inner.x = pOut[0];
        inner.y = pOut[1];
        inner.w = pOut[2];
        inner.h = pOut[3];

        // Frustum culling: if completely off-screen, skip
        if (root != null) {
            float viewHeight = root.getHeight();
            // Test intersection with outer rect to be safe, since inner might be larger
            if (outer.y + outer.h < 0 || outer.y > viewHeight) {
                return;
            }
        }

        // Apply clipping to the outer bounds so COVER / FIT overflowing doesn't leak out of the cell
        Shape oldClip = g.getClip();
        clipRect.setRect(outer.x, outer.y, outer.w, outer.h);
        g.clip(clipRect);

        if (image != null) {
            transform.setToIdentity();
            transform.translate(inner.x, inner.y);
            transform.scale(inner.w / image.getWidth(), inner.h / image.getHeight());
            g.drawImage(image, transform, null);
        } else {
            // Fallback: white rectangle
            g.setColor(Color.WHITE);
            fallbackRect.setRect(inner.x, inner.y, inner.w, inner.h);
            g.fill(fallbackRect);
        }

        // Restore original clip
        g.setClip(oldClip);
    }
}

