package fastgrid;

public final class Rect {
    public float x, y, w, h;

    public Rect() {}

    public Rect(float x, float y, float w, float h) {
        this.x = x; this.y = y; this.w = w; this.h = h;
    }

    public void set(float x, float y, float w, float h) {
        this.x = x; this.y = y; this.w = w; this.h = h;
    }

    public void set(Rect other) {
        this.x = other.x;
        this.y = other.y;
        this.w = other.w;
        this.h = other.h;
    }

    public void setLerp(Rect a, Rect b, float t) {
        this.x = a.x + (b.x - a.x) * t;
        this.y = a.y + (b.y - a.y) * t;
        this.w = a.w + (b.w - a.w) * t;
        this.h = a.h + (b.h - a.h) * t;
    }

    // Optional legacy helper
    public static Rect lerp(Rect a, Rect b, float t) {
        Rect r = new Rect();
        r.setLerp(a, b, t);
        return r;
    }
}

package fastgrid;

import java.util.List;

public interface LayoutAlgorithm {

    LayoutMeasure measure(List<Cell> cells, LayoutContext ctx);

    List<Rect> arrange(List<Cell> cells, LayoutContext ctx, LayoutMeasure measure);
}

package fastgrid;

import java.util.List;

public final class GalleryRows {

    public record Row(int start, int count, float rowH, float scale) {}

    public static Row packRow(
            List<Cell> cells,
            int start,
            float targetHeight,
            float gap,
            float width,
            float minSize
    ) {
        float rowSum = 0f;
        int count = 0;
        int i = start;

        while (i < cells.size()) {
            float w = LayoutMath.widthFor(cells.get(i), targetHeight, minSize);
            float next = rowSum + w;
            float gaps = gap * (count + 2);

            if (count > 0 && next + gaps > width)
                break;

            rowSum = next;
            count++;
            i++;
        }

        if (count == 0) {
            count = 1;
            rowSum = LayoutMath.widthFor(cells.get(start), targetHeight, minSize);
        }

        float gaps         = gap * (count + 1);
        float targetContent = width - gaps;
        float scale        = targetContent / rowSum;
        float rowH         = targetHeight * scale;

        return new Row(start, count, rowH, scale);
    }
}

package fastgrid.demo;

import fastgrid.*;

import fastanimation.FastAnimation;
import fastanimation.Animation;
import fasttween.FastTween;
import fasttween.Tween;

public class AnimationController {

    private final FastGridView panel;
    private final LayoutController layout;

    private Animation layoutAnim;
    private Animation columnAnim;

    public AnimationController(FastGridView panel, LayoutController layout) {
        this.panel = panel;
        this.layout = layout;
    }

    public void animateLayout(LayoutMode target) {
        if (layoutAnim != null && layoutAnim.isRunning()) {
            layoutAnim.stop();
        }

        // setMode snapshots current visual state and resets t=0 internally
        layout.setMode(target);

        Tween tween = FastTween.to(0f, 1f, 400)
                .ease(fasttween.Ease.CUBIC_OUT)
                .onUpdate(val -> {
                    layout.setLayoutT(val);
                    panel.repaint();
                })
                .onComplete(() -> {
                    layout.setLayoutT(1f);
                    panel.repaint();
                });

        layoutAnim = FastAnimation.sequence(tween).start();
    }

    public void snapColumns(float currentColumns) {
        float snapped = Math.max(2f, Math.round(currentColumns));
        float start = currentColumns;
        float end   = snapped;

        if (columnAnim != null && columnAnim.isRunning()) {
            columnAnim.stop();
        }

        Tween tween = FastTween.to(start, end, 300)
                .ease(fasttween.Ease.CUBIC_OUT)
                .onUpdate(val -> {
                    panel.columns = val;
                    panel.targetColumns = val;
                    layout.invalidate();
                    panel.repaint();
                })
                .onComplete(() -> {
                    panel.columns = end;
                    panel.targetColumns = end;
                    layout.invalidate();
                    panel.repaint();
                });

        columnAnim = FastAnimation.sequence(tween).start();
    }
}

package fastgrid;

import java.util.List;

public final class GalleryLayout implements LayoutAlgorithm {

    @Override
    public LayoutMeasure measure(List<Cell> cells, LayoutContext ctx) {
        float targetH = ctx.columnWidth();
        float y = ctx.gap();
        int index = 0;
        int n = cells.size();

        while (index < n) {
            GalleryRows.Row row = GalleryRows.packRow(cells, index, targetH, ctx.gap(), ctx.width(), ctx.minSize());
            y += row.rowH() + ctx.gap();
            index += row.count();
        }

        return new LayoutMeasure(y);
    }

    @Override
    public List<Rect> arrange(List<Cell> cells, LayoutContext ctx, LayoutMeasure m) {
        float targetH = ctx.columnWidth();
        float gap = ctx.gap();

        Rect[] out = new Rect[cells.size()];
        float y = gap;
        int index = 0;
        int n = cells.size();

        while (index < n) {
            GalleryRows.Row row = GalleryRows.packRow(cells, index, targetH, gap, ctx.width(), ctx.minSize());
            int rowStart = index;
            int count = row.count();
            float rowH = row.rowH();
            float scale = row.scale();

            // Last row: do NOT justify — left-align it
            boolean isLastRow = (index + count >= n);
            float x = gap;

            for (int i = 0; i < count; i++) {
                Cell c = cells.get(rowStart + i);
                float baseW = LayoutMath.widthFor(c, targetH, ctx.minSize());
                float w = isLastRow ? baseW : baseW * scale;

                out[rowStart + i] = new Rect(x, y, w, isLastRow ? targetH : rowH);
                x += w + gap;
            }

            y += rowH + gap;
            index += count;
        }

        // Convert to list (already allocated once via array)
        return java.util.Arrays.asList(out);
    }
}

package fastgrid;

public final class LayoutMath {

    // Höhe bei gegebener Breite (Masonry-Spalte etc.)
    public static float heightFor(Cell c, float targetWidth, float minSize) {
        float h = targetWidth * (c.ratioH / c.ratioW);
        return Math.max(minSize, h);
    }

    // Breite bei gegebener Höhe (Gallery-Zeile etc.)
    public static float widthFor(Cell c, float targetHeight, float minSize) {
        float w = targetHeight * (c.ratioW / c.ratioH);
        return Math.max(minSize, w);
    }

    public static int minIndex(float[] arr) {
        int best = 0;
        for (int i = 1; i < arr.length; i++)
            if (arr[i] < arr[best]) best = i;
        return best;
    }
}

package fastgrid.demo;

import fastgrid.Cell;
import fastgrid.Rect;
import fastproportion.ProportionMode;
import fastui.component.Component;

import javax.imageio.ImageIO;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class FastGridView extends Component {

    public float columns       = 5f;
    public float targetColumns  = 5f;
    public float gapScale      = 1f;
    public final float baseGap  = 10f;
    public float scrollY        = 0f;

    public ProportionMode proportionMode = ProportionMode.CONTAIN;

    // Loading callback: (loaded, total)
    public java.util.function.BiConsumer<Integer, Integer> onProgress;

    // FPS callback
    public java.util.function.Consumer<Integer> onFpsUpdate;

    public final LayoutController layout;
    public final InteractionController input;
    public final AnimationController anim;

    public FastGridView() {
        this.setHitTestable(true);
        this.layout = new LayoutController(this);
        this.anim   = new AnimationController(this, layout);
        this.input  = new InteractionController(this, layout, anim);
    }

    /**
     * Finds all images recursively in the directory.
     * Extracts their true aspect ratio to create perfectly fitting Cells.
     */
    public void loadImages(File imageDir) {
        if (!imageDir.exists() || !imageDir.isDirectory()) return;

        List<File> allFiles = new ArrayList<>();
        findImagesRecursively(imageDir, allFiles);

        System.out.println("Found " + allFiles.size() + " image files in " + imageDir.getAbsolutePath());
        if (allFiles.isEmpty()) return;

        Thread loader = new Thread(() -> {
            int MULTIPLIER = 10;
            List<Cell> newCells = new ArrayList<>(allFiles.size() * MULTIPLIER);
            List<CellComponent> newComponents = new ArrayList<>(allFiles.size() * MULTIPLIER);

            int index = 0;
            for (int m = 0; m < MULTIPLIER; m++) {
                for (File f : allFiles) {
                    try {
                        BufferedImage raw = ImageIO.read(f);
                        if (raw != null) {
                            float rw = raw.getWidth();
                            float rh = raw.getHeight();

                            // Cap width at 600px to save Heap & VRAM
                            float scale = Math.min(1f, 600f / rw);
                            int tw = (int) (rw * scale);
                            int th = (int) (rh * scale);

                            // Convert to hardware-accelerated VRAM compatible image
                            GraphicsConfiguration gc = GraphicsEnvironment.getLocalGraphicsEnvironment()
                                    .getDefaultScreenDevice().getDefaultConfiguration();
                            BufferedImage img = gc.createCompatibleImage(tw, th, Transparency.TRANSLUCENT);
                            Graphics2D g = img.createGraphics();
                            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                            g.drawImage(raw, 0, 0, tw, th, null);
                            g.dispose();

                            Cell cell = new Cell(rw, rh);
                            cell.index = index++;

                            CellComponent comp = new CellComponent(FastGridView.this, cell);
                            comp.image = img;

                            newCells.add(cell);
                            newComponents.add(comp);

                            // Progress callback
                            if (onProgress != null) {
                                int loadedCount = newCells.size();
                                int totalCount = allFiles.size() * MULTIPLIER;
                                EventQueue.invokeLater(() -> onProgress.accept(loadedCount, totalCount));
                            }

                            // Progressive load: update UI every 5 images
                            if (newCells.size() % 5 == 0) {
                                List<Cell> batchCells = new ArrayList<>(newCells);
                                List<CellComponent> batchComps = new ArrayList<>(newComponents);
                                EventQueue.invokeLater(() -> {
                                    if (this.children != null) this.children.clear();
                                    for (CellComponent c : batchComps) this.add(c);
                                    layout.setCells(batchCells);
                                    repaint();
                                });
                            }
                        }
                    } catch (IOException ignored) {}
                }
            }

            System.out.println("Successfully loaded " + newCells.size() + " images.");

            EventQueue.invokeLater(() -> {
                if (this.children != null) this.children.clear();
                for (CellComponent comp : newComponents) this.add(comp);
                layout.setCells(newCells);

                if (onProgress != null) {
                    int totalCount = allFiles.size() * MULTIPLIER;
                    onProgress.accept(totalCount, totalCount);
                }

                repaint();
            });
        }, "image-loader");

        loader.setDaemon(true);
        loader.start();
    }

    private void findImagesRecursively(File dir, List<File> result) {
        File[] files = dir.listFiles();
        if (files == null) return;
        for (File f : files) {
            if (f.isDirectory()) {
                findImagesRecursively(f, result);
            } else {
                String lower = f.getName().toLowerCase();
                if (lower.endsWith(".jpg") || lower.endsWith(".jpeg") || lower.endsWith(".png") || lower.endsWith(".webp")) {
                    result.add(f);
                }
            }
        }
    }

    public void scroll(float dy) {
        scrollY += dy;
        if (scrollY > 0) scrollY = 0;

        float contentHeight = (float) layout.getPreferredSize().getHeight();
        float viewHeight    = root != null ? root.getHeight() : 610f;
        float minScroll     = contentHeight > viewHeight ? -(contentHeight - viewHeight) : 0f;
        if (scrollY < minScroll) scrollY = minScroll;

        repaint();
    }

    // FPS tracking
    private long lastFpsTime = 0;
    private int frames = 0;
    private int currentFps = 0;

    @Override
    public void onRender(Graphics2D g) {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

        long now = System.nanoTime();
        frames++;
        if (now - lastFpsTime >= 1_000_000_000L) {
            currentFps = frames;
            frames = 0;
            lastFpsTime = now;
            if (onFpsUpdate != null) {
                int fps = currentFps;
                EventQueue.invokeLater(() -> onFpsUpdate.accept(fps));
            }
        }

        if (root != null) {
            if (this.width != root.getWidth()) {
                layout.invalidate();
            }
            this.width  = root.getWidth();
            this.height = root.getHeight();
        }

        Rect[] rects = layout.getRects();
        List<Cell> cells = layout.getCells();

        if (this.children == null || this.children.size() != cells.size()) return;

        for (int i = 0; i < cells.size(); i++) {
            Rect r = rects[i];
            Cell c = cells.get(i);

            float drawY = r.y + scrollY;
            c.outer.set(r.x, drawY, r.w, r.h);

            Component child = this.children.get(i);
            child.setBounds(r.x, drawY, r.w, r.h);
        }
    }
}

package fastgrid.benchmark;

import fastgrid.*;
import org.openjdk.jmh.annotations.*;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.TimeUnit;

@State(Scope.Thread)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(1)
public class JMH_Grid {

    private static final int   ITEM_COUNT        = 500;
    private static final int   COLUMNS           = 5;
    private static final float CONTAINER_WIDTH   = 1920f;
    private static final float GAP               = 10f;
    private static final float MIN_SIZE          = 24f;

    private List<Cell> cells;
    private LayoutAlgorithm gridAlgo;
    private LayoutAlgorithm masonryAlgo;
    private LayoutAlgorithm galleryAlgo;

    @Setup(Level.Trial)
    public void setup() {
        float[][] RATIOS = {
                {1, 1}, {4, 3}, {3, 4}, {16, 9}, {9, 16}, {3, 2}, {2, 3}
        };

        Random rand = new Random(42);
        cells = new ArrayList<>(ITEM_COUNT);
        for (int i = 0; i < ITEM_COUNT; i++) {
            float[] r = RATIOS[rand.nextInt(RATIOS.length)];
            cells.add(new Cell(r[0], r[1]));
        }

        gridAlgo    = new GridLayout();
        masonryAlgo = new MasonryLayout();
        galleryAlgo = new GalleryLayout();
    }

    @Benchmark
    public List<Rect> computeGridLayout() {
        LayoutContext ctx = LayoutContext.of(CONTAINER_WIDTH, GAP, MIN_SIZE, COLUMNS);
        LayoutMeasure m   = gridAlgo.measure(cells, ctx);
        return gridAlgo.arrange(cells, ctx, m);
    }

    @Benchmark
    public List<Rect> computeMasonryLayout() {
        LayoutContext ctx = LayoutContext.of(CONTAINER_WIDTH, GAP, MIN_SIZE, COLUMNS);
        LayoutMeasure m   = masonryAlgo.measure(cells, ctx);
        return masonryAlgo.arrange(cells, ctx, m);
    }

    @Benchmark
    public List<Rect> computeGalleryLayout() {
        LayoutContext ctx = LayoutContext.of(CONTAINER_WIDTH, GAP, MIN_SIZE, COLUMNS);
        LayoutMeasure m   = galleryAlgo.measure(cells, ctx);
        return galleryAlgo.arrange(cells, ctx, m);
    }
}

package fastgrid.demo;

import fasttheme.FastTheme;
import fastui.Container;
import fastgrid.LayoutMode;
import fastproportion.ProportionMode;

import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.image.BufferedImage;
import java.io.File;

public class Demo {

    private static final int WIDTH  = 1173;
    private static final int HEIGHT = 610;

    public static void main(String[] args) {

        System.setProperty("sun.java2d.uiScale",         "1.0");
        System.setProperty("sun.java2d.opengl",          "true");
        System.setProperty("sun.java2d.opengl.fbobject", "true");
        System.setProperty("sun.java2d.d3d",             "false");

        JFrame frame = new JFrame("FastGrid + FastUI");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(WIDTH, HEIGHT);
        frame.setLocationRelativeTo(null);
        frame.setIconImage(createRoundIcon());

        Container root = new Container();
        root.setBackground(Color.BLACK);

        FastGridView view = new FastGridView();
        root.add(view);

        // Resolve image directory safely
        String userDir = System.getProperty("user.dir");
        File imageDir = new File(userDir.contains("examples") ? 
                                 "src/main/resources/images" : 
                                 "examples/Demo/src/main/resources/images");

        int[] stats = new int[]{0, 0, 0}; // loaded, total, fps
        Runnable updateTitle = () -> {
            frame.setTitle(String.format("FastGrid + FastUI [%d/%d] - %d FPS", stats[0], stats[1], stats[2]));
        };

        view.onProgress = (loaded, total) -> {
            stats[0] = loaded;
            stats[1] = total;
            updateTitle.run();
        };

        view.onFpsUpdate = (fps) -> {
            stats[2] = fps;
            updateTitle.run();
        };

        view.loadImages(imageDir);

        // ── Keyboard shortcuts ──────────────────────────────────
        InputMap  im = root.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW);
        ActionMap am = root.getActionMap();

        im.put(KeyStroke.getKeyStroke("1"), "grid-contain");
        im.put(KeyStroke.getKeyStroke("2"), "grid-cover");
        im.put(KeyStroke.getKeyStroke("3"), "grid-fith");
        im.put(KeyStroke.getKeyStroke("4"), "grid-fitv");
        im.put(KeyStroke.getKeyStroke("5"), "masonry");
        im.put(KeyStroke.getKeyStroke("6"), "gallery");

        am.put("grid-contain", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) { 
                view.proportionMode = ProportionMode.CONTAIN;
                view.anim.animateLayout(LayoutMode.GRID); 
                view.repaint();
            }
        });
        am.put("grid-cover", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) { 
                view.proportionMode = ProportionMode.COVER;
                view.anim.animateLayout(LayoutMode.GRID); 
                view.repaint();
            }
        });
        am.put("grid-fith", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) { 
                view.proportionMode = ProportionMode.FIT_HORIZONTAL;
                view.anim.animateLayout(LayoutMode.GRID); 
                view.repaint();
            }
        });
        am.put("grid-fitv", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) { 
                view.proportionMode = ProportionMode.FIT_VERTICAL;
                view.anim.animateLayout(LayoutMode.GRID); 
                view.repaint();
            }
        });
        am.put("masonry", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) { 
                view.proportionMode = ProportionMode.FIT_HORIZONTAL; // Masonry inherently uses FIT_HORIZONTAL
                view.anim.animateLayout(LayoutMode.MASONRY); 
                view.repaint();
            }
        });
        am.put("gallery", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) { 
                view.proportionMode = ProportionMode.FIT_VERTICAL; // Gallery inherently uses FIT_VERTICAL
                view.anim.animateLayout(LayoutMode.GALLERY); 
                view.repaint();
            }
        });

        // ── Mouse (scroll, zoom, gap) ────────────────────────────
        root.addMouseListener(view.input.mouseListener);
        root.addMouseMotionListener(view.input.mouseMotionListener);
        root.addMouseWheelListener(view.input.wheelListener);

        frame.setContentPane(root);
        frame.addNotify();

        long hwnd = FastTheme.getWindowHandle(frame);
        if (hwnd != 0) {
            FastTheme.setTitleBarColor(hwnd, 0, 0, 0);
            FastTheme.setTitleBarTextColor(hwnd, 255, 255, 255);
            // FastTheme.setWindowTransparency(hwnd, 230);
        }

        frame.setVisible(true);
        SwingUtilities.invokeLater(root::requestFocusInWindow);
    }

    private static BufferedImage createRoundIcon() {
        BufferedImage icon = new BufferedImage(64, 64, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = icon.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(Color.WHITE);
        g.fillOval(4, 4, 56, 56);
        g.dispose();
        return icon;
    }
}
